model Ball {
  x: Number
  y: Number
  vx: Number
  vy: Number
  r: Number
}

component Simulation {
  state balls: Ball[] = []
  state paused = false
  state frameCount = 0
  ref canvas
  ref animationId

  fn initBalls {
    balls = []
    for (let i = 0; i < 5; i++) {
      balls.push({
        x: Math.random() * 380 + 10,
        y: Math.random() * 280 + 10,
        vx: Math.random() * 4 - 2,
        vy: Math.random() * 4 - 2,
        r: 10
      })
    }
    frameCount = 0
  }

  fn addBall {
    balls.push({
      x: Math.random() * 380 + 10,
      y: Math.random() * 280 + 10,
      vx: Math.random() * 4 - 2,
      vy: Math.random() * 4 - 2,
      r: 10
    })
  }

  fn togglePause {
    paused = !paused
  }

  fn updatePhysics {
    for b in balls {
      b.vy += 0.2
      b.x += b.vx
      b.y += b.vy

      if b.x - b.r < 0 {
        b.x = b.r
        b.vx = -b.vx
      }
      if b.x + b.r > 400 {
        b.x = 400 - b.r
        b.vx = -b.vx
      }
      if b.y - b.r < 0 {
        b.y = b.r
        b.vy = -b.vy
      }
      if b.y + b.r > 300 {
        b.y = 300 - b.r
        b.vy = -b.vy
      }
    }

    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        let b1 = balls[i]
        let b2 = balls[j]
        let dx = b2.x - b1.x
        let dy = b2.y - b1.y
        let dist = Math.sqrt(dx * dx + dy * dy)

        if dist < b1.r + b2.r {
          let temp = b1.vx
          b1.vx = b2.vx
          b2.vx = temp
          temp = b1.vy
          b1.vy = b2.vy
          b2.vy = temp
        }
      }
    }
  }

  fn draw {
    let ctx = canvas.getContext("2d")
    ctx.fillStyle = "#fff"
    ctx.fillRect(0, 0, 400, 300)
    ctx.fillStyle = "#000"
    ctx.strokeStyle = "#333"
    ctx.lineWidth = 1

    for b in balls {
      ctx.beginPath()
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
      ctx.fill()
      ctx.stroke()
    }
  }

  fn animate {
    if !paused {
      updatePhysics()
      frameCount++
    }
    draw()
    animationId = requestAnimationFrame(animate)
  }

  mount {
    initBalls()
    draw()
    animationId = requestAnimationFrame(animate)
    cleanup {
      if animationId {
        cancelAnimationFrame(animationId)
      }
    }
  }

  column gap=4 pad=4 {
    row gap=2 {
      button "Agregar" primary -> addBall()
      button (paused ? "Reanudar" : "Pausar") -> togglePause()
      button "Reiniciar" danger -> initBalls()
    }
    row gap=4 {
      text `Pelotas: ${balls.length}`
      text `Cuadros: ${frameCount}`
    }
    canvas ref=canvas width=400 height=300 style="border: 1px solid #ccc; background: #f9f9f9"
  }
}

