interface Ball {
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
}

let balls: Ball[] = [];
let animationId: number | null = null;
let frameCount = 0;
let isPaused = false;

const GRAVITY = 0.2;
const CANVAS_WIDTH = 400;
const CANVAS_HEIGHT = 300;
const BALL_RADIUS = 10;

function createBall(): Ball {
  return {
    x: Math.random() * (CANVAS_WIDTH - 2 * BALL_RADIUS) + BALL_RADIUS,
    y: Math.random() * (CANVAS_HEIGHT - 2 * BALL_RADIUS) + BALL_RADIUS,
    vx: (Math.random() - 0.5) * 8,
    vy: (Math.random() - 0.5) * 8,
    radius: BALL_RADIUS,
  };
}

export function init(canvas: HTMLCanvasElement) {
  balls = Array.from({ length: 5 }, () => createBall());
  frameCount = 0;
  isPaused = false;
  animate(canvas);
}

export function addBall(canvas: HTMLCanvasElement) {
  balls.push(createBall());
  if (!isPaused) animate(canvas);
}

export function togglePause(canvas: HTMLCanvasElement) {
  isPaused = !isPaused;
  if (!isPaused) animate(canvas);
}

export function reset(canvas: HTMLCanvasElement) {
  balls = Array.from({ length: 5 }, () => createBall());
  frameCount = 0;
  isPaused = false;
  draw(canvas);
  animate(canvas);
}

export function getBallCount() {
  return balls.length;
}

export function getFrameCount() {
  return frameCount;
}

function animate(canvas: HTMLCanvasElement) {
  if (isPaused) return;

  frameCount++;

  // Update physics
  for (let ball of balls) {
    ball.vy += GRAVITY;
    ball.x += ball.vx;
    ball.y += ball.vy;

    // Bounce off walls
    if (ball.x - ball.radius < 0) {
      ball.x = ball.radius;
      ball.vx = Math.abs(ball.vx);
    }
    if (ball.x + ball.radius > CANVAS_WIDTH) {
      ball.x = CANVAS_WIDTH - ball.radius;
      ball.vx = -Math.abs(ball.vx);
    }
    if (ball.y - ball.radius < 0) {
      ball.y = ball.radius;
      ball.vy = Math.abs(ball.vy);
    }
    if (ball.y + ball.radius > CANVAS_HEIGHT) {
      ball.y = CANVAS_HEIGHT - ball.radius;
      ball.vy = -Math.abs(ball.vy);
    }
  }

  // Collision detection and response
  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const ball1 = balls[i];
      const ball2 = balls[j];
      const dx = ball2.x - ball1.x;
      const dy = ball2.y - ball1.y;
      const distance = Math.sqrt(dx * dx + dy * dy);
      const minDistance = ball1.radius + ball2.radius;

      if (distance < minDistance) {
        // Elastic collision - swap velocities
        const temp = ball1.vx;
        ball1.vx = ball2.vx;
        ball2.vx = temp;

        const temp2 = ball1.vy;
        ball1.vy = ball2.vy;
        ball2.vy = temp2;

        // Separate balls to prevent overlap
        const overlap = (minDistance - distance) / 2;
        const angle = Math.atan2(dy, dx);
        ball1.x -= overlap * Math.cos(angle);
        ball1.y -= overlap * Math.sin(angle);
        ball2.x += overlap * Math.cos(angle);
        ball2.y += overlap * Math.sin(angle);
      }
    }
  }

  draw(canvas);
  animationId = requestAnimationFrame(() => animate(canvas));
}

function draw(canvas: HTMLCanvasElement) {
  const ctx = canvas.getContext("2d");
  if (!ctx) return;

  ctx.fillStyle = "#fff";
  ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

  for (let ball of balls) {
    ctx.fillStyle = "#e11d48";
    ctx.beginPath();
    ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
    ctx.fill();
  }
}

